from __future__ import annotations
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Generic, TypeVar, Any

T = TypeVar("T")


class Option(ABC, Generic[T]):
    @abstractmethod
    def is_some(self) -> bool:
        pass

    @abstractmethod
    def is_none(self) -> bool:
        pass

    @abstractmethod
    def unwrap(self) -> T:
        pass


@dataclass(frozen=True)
class Some(Option[T]):
    value: T

    def is_some(self) -> bool:
        return True

    def is_none(self) -> bool:
        return False

    def unwrap(self) -> T:
        return self.value


class NoneOption(Option[Any]):
    _instance: "NoneOption" | None = None

    def __new__(cls) -> "NoneOption":
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def is_some(self) -> bool:
        return False

    def is_none(self) -> bool:
        return True

    def unwrap(self) -> Any:
        raise ValueError("Called unwrap on NoneOption")


NONE = NoneOption()


def safe_divide(numerator: float, denominator: float) -> Option[float]:
    if denominator == 0:
        return NONE
    return Some(numerator / denominator)


def print_result(result: Option[float]) -> None:
    if result.is_some():
        # type: ignore[attr-defined]
        print(f"Result: {result.unwrap()}")
    else:
        print("Error: Division by zero")


def main() -> None:
    r1 = safe_divide(10, 2)
    r2 = safe_divide(10, 0)
    print_result(r1)
    print_result(r2)


if __name__ == "__main__":
    main()

