import std/io (readFile, writeFile, println)
import std/json (decode, Json, JObject, JString, JNumber, JArray, JNull)
import std/list (length, map)
import std/string (split)
import std/result (Result, Ok, Err)

type Config = {
  app_name: string,
  version: string,
  port: int,
  features: List[string]
}

-- Default/error config to return if parsing or validation fails
let defaultConfig: Config = {
  app_name: "UNKNOWN_APP",
  version: "0.0.0",
  port: 0,
  features: []
}

-- Helper to validate port range
pure func validatePort(port: int) -> bool =
  port >= 1024 && port <= 65535

-- Helper to validate version format (contains exactly two dots)
pure func validateVersion(ver: string) -> bool =
  length(split(ver, ".")) == 3

-- Helper to extract a field value from a list of key-value pairs (from a JObject)
pure func getFieldFromKVs(kvs: List[{key: string, value: Json}], field: string) -> Json {
  match kvs {
    [] => JNull,
    [kv, ...rest] =>
      if kv.key == field then kv.value else getFieldFromKVs(rest, field)
  }
}

-- Helper to extract a field from a Json value (expected to be a JObject)
-- Returns JNull if the field is not found or json is not a JObject
pure func getField(json: Json, field: string) -> Json {
  match json {
    JObject(kvs) => getFieldFromKVs(kvs, field),
    _ => JNull
  }
}

-- Helper to safely convert JString to string
pure func jsonStringToString(json: Json) -> string {
  match json {
    JString(s) => s,
    _ => "" -- Return empty string for non-string JSON values
  }
}

-- Helper to safely convert JNumber to int
pure func jsonNumberToInt(json: Json) -> int {
  match json {
    JNumber(f) => floatToInt(f),
    _ => 0 -- Return 0 for non-number JSON values or if not found
  }
}

-- Helper to safely convert JArray of JStrings to List[string]
pure func jsonArrayToStringList(json: Json) -> List[string] {
  match json {
    JArray(arr) => map(jsonStringToString, arr),
    _ => [] -- Return empty list for non-array JSON values
  }
}

export func loadConfig(filename: string) -> Config ! {FS} {
  let content = readFile(filename);
  match decode(content) {
    Ok(json) =>
      match json {
        JObject(kvs) => {
          let appNameJson = getField(json, "app_name");
          let versionJson = getField(json, "version");
          let portJson = getField(json, "port");
          let featuresJson = getField(json, "features");

          let app_name = jsonStringToString(appNameJson);
          let version = jsonStringToString(versionJson);
          let port = jsonNumberToInt(portJson);
          let features = jsonArrayToStringList(featuresJson);

          -- Perform all necessary validations
          if app_name != "" &&
             version != "" && validateVersion(version) &&
             port != 0 && validatePort(port) &&
             length(features) > 0
          then
            { app_name: app_name, version: version, port: port, features: features }
          else
            defaultConfig -- Validation or extraction failed
        },
        _ => defaultConfig -- The top-level JSON was not an object
      },
    Err(_) => defaultConfig -- JSON parsing failed (e.g., malformed JSON)
  }
}

export func main() -> () ! {IO, FS} {
  -- Create config file
  let configJson = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  writeFile("app_config.json", configJson);

  -- Load and validate config
  let config = loadConfig("app_config.json");

  -- Print result
  let numFeatures = length(config.features);
  println("Loaded " ++ config.app_name ++ " v" ++ config.version ++ " on port " ++ show(config.port) ++ " with " ++ show(numFeatures) ++ " features")
}

