import std/io (println)
import std/fs (readFile, writeFile)
import std/string (split, find, stringToInt, trim)
import std/json (encode, jo, kv, js, jnum, Json, ja)
import std/option (Option, Some, None)
import std/list (map, length, filter)

-- Define the User record type
type User = {name: string, age: int, email: string}

-- Helper function to check if email contains '@'
export pure func isValidEmail(email: string) -> bool
  tests [
    ("test@example.com", true),
    ("invalid-email", false),
    ("no@domain", true)
  ]
{
  find(email, "@") != -1
}

-- Helper function to parse age string to int and ensure it's positive
export pure func parsePositiveInt(s: string) -> Option[int]
  tests [
    ("30", Some(30)),
    ("0", None),
    ("-5", None),
    ("abc", None)
  ]
{
  match stringToInt(s) {
    Some(n) => if n > 0 then Some(n) else None,
    None => None
  }
}

-- Validates and parses a single row (list of strings) into an Option[User] record.
-- Assumes fields are in order: name, age, email. Fields are expected to be trimmed.
export pure func parseUserRow(fields: [string]) -> Option[User]
  tests [
    (["Alice", "30", "alice@example.com"], Some({name: "Alice", age: 30, email: "alice@example.com"})),
    (["Bob", "0", "bob@example.com"], None), -- Invalid age
    (["Carol", "35", "invalid-email"], None), -- Invalid email
    (["David", "40"], None), -- Too few fields
    (["Eve", "50", "eve@example.com", "extra"], None) -- Too many fields
  ]
{
  match fields {
    [name, ageStr, email] =>
      if isValidEmail(email)
      then match parsePositiveInt(ageStr) {
        Some(age) => Some({name: name, age: age, email: email}),
        None => None
      }
      else None,
    _ => None -- Incorrect number of fields
  }
}

-- Recursively processes all data rows, returning a list of valid User records.
-- This effectively acts as a filter-map operation over Option[User].
export pure func processCsvData(dataRows: [[string]]) -> [User]
  tests [
    ([], []),
    ([["Alice", "30", "alice@example.com"]], [({name: "Alice", age: 30, email: "alice@example.com"})]),
    ([["Valid", "10", "valid@a.com"], ["Invalid", "0", "invalid@b.com"]], [({name: "Valid", age: 10, email: "valid@a.com"})]),
    ([["A", "1", "a@a.com"], ["B", "0", "b@b.com"], ["C", "2", "c@c.com"]], [({name: "A", age: 1, email: "a@a.com"}), ({name: "C", age: 2, email: "c@c.com"})])
  ]
{
  match dataRows {
    [] => [],
    row :: rest => match parseUserRow(row) {
      Some(user) => user :: processCsvData(rest),
      None => processCsvData(rest)
    }
  }
}

-- Converts a User record to a JSON object
export pure func userToJson(user: User) -> Json
  tests [
    ({name: "Alice", age: 30, email: "alice@example.com"}, jo([kv("name", js("Alice")), kv("age", jnum(30.0)), kv("email", js("alice@example.com"))]))
  ]
{
  jo([
    kv("name", js(user.name)),
    kv("age", jnum(intToFloat(user.age))), -- jnum expects a float
    kv("email", js(user.email))
  ])
}

-- Main function to orchestrate CSV to JSON conversion
export func main() -> () ! {IO, FS} {
  -- 1. Create input CSV file "users.csv" with the exact content specified in the task
  let csvContent = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com";
  writeFile("users.csv", csvContent);

  -- 2. Parse the CSV file
  let rawCsv = readFile("users.csv");
  let allLines = split(rawCsv, "\n");

  -- Trim and filter out any empty lines (e.g., from trailing newlines or blank lines)
  let trimmedLines = map(\s. trim(s), allLines);
  let filteredLines = filter(\s. s != "", trimmedLines);

  match filteredLines {
    headerLine :: dataLines => {
      -- Trim each field after splitting the line
      let parsedDataRows = map(\line. map(trim, split(line, ",")), dataLines);

      -- 3. Validate each row and accumulate valid users
      let validUsers = processCsvData(parsedDataRows);

      -- 4. Convert to JSON array
      let jsonUsers = map(userToJson, validUsers);
      let finalJsonString = encode(ja(jsonUsers));

      -- 5. Write JSON to "users.json" file
      writeFile("users.json", finalJsonString);

      -- 6. Print to stdout the count of converted rows
      println("Converted " ++ show(length(validUsers)) ++ " valid rows to users.json")
    },
    [] => println("Error: CSV file is empty or contains only blank lines.")
  }
}

