import csv
import json
from pathlib import Path


def create_csv_file(filepath: Path) -> None:
    content = """name,age,email
Alice,30,alice@example.com
Bob,25,bob@example.com
Carol,35,carol@example.com"""
    filepath.write_text(content)


def validate_row(row: dict) -> bool:
    try:
        age = int(row.get("age", ""))
        if age <= 0:
            return False
    except ValueError:
        return False

    email = row.get("email", "")
    if "@" not in email:
        return False

    return True


def parse_csv(filepath: Path) -> list[dict]:
    valid_rows = []
    with open(filepath, newline="") as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            if validate_row(row):
                valid_rows.append({
                    "name": row["name"],
                    "age": int(row["age"]),
                    "email": row["email"]
                })
    return valid_rows


def write_json(data: list[dict], filepath: Path) -> None:
    with open(filepath, "w") as jsonfile:
        json.dump(data, jsonfile, indent=2)


def main() -> None:
    csv_path = Path("users.csv")
    json_path = Path("users.json")

    create_csv_file(csv_path)
    valid_rows = parse_csv(csv_path)
    write_json(valid_rows, json_path)

    print(f"Converted {len(valid_rows)} valid rows to {json_path}")


if __name__ == "__main__":
    main()

