from typing import TypeVar, Generic, Callable

T = TypeVar('T')
A = TypeVar('A')
B = TypeVar('B')

class Pure(Generic[T]):
    """Wrapper for pure values - cannot contain IO effects"""
    def __init__(self, value: T):
        self._value = value

    def get(self) -> T:
        return self._value

    def map(self, f: Callable[[T], A]) -> 'Pure[A]':
        return Pure(f(self._value))

class IO(Generic[T]):
    """Wrapper for effectful computations"""
    def __init__(self, effect: Callable[[], T]):
        self._effect = effect

    def run(self) -> T:
        return self._effect()

    def map(self, f: Callable[[T], A]) -> 'IO[A]':
        return IO(lambda: f(self._effect()))

    def flat_map(self, f: Callable[[T], 'IO[A]']) -> 'IO[A]':
        return IO(lambda: f(self._effect()).run())

def double(x: int) -> Pure[int]:
    """PURE: Returns x * 2 with no side effects"""
    return Pure(x * 2)

def add(a: int, b: int) -> Pure[int]:
    """PURE: Returns a + b with no side effects"""
    return Pure(a + b)

def printResult(label: str, value: int) -> IO[None]:
    """EFFECTFUL: Prints label and value (has IO)"""
    def effect():
        print(f"{label}: {value}")
        return None
    return IO(effect)

def compute_and_print() -> IO[None]:
    """EFFECTFUL: Computes result using pure functions and prints it"""
    def effect():
        # Call pure functions - they return Pure wrappers
        result1 = double(5)
        result2 = add(result1.get(), 3)
        # Call effectful function with the pure result
        printResult("Result", result2.get()).run()
        return None
    return IO(effect)

if __name__ == "__main__":
    compute_and_print().run()

