import re
from pathlib import Path
from typing import Dict, Set, List, Tuple

LOG_CONTENT = """2024-10-29 10:00:00 INFO User logged in: alice
2024-10-29 10:01:15 ERROR Database connection failed
2024-10-29 10:02:30 INFO User logged in: bob
2024-10-29 10:03:45 WARNING High memory usage: 85%
2024-10-29 10:05:00 ERROR API timeout: /users endpoint
2024-10-29 10:06:15 INFO User logged out: alice"""

LOG_FILENAME = "app.log"

def create_log_file(filename: Path, content: str) -> None:
    filename.write_text(content)

def parse_log_line(line: str) -> Dict[str, str] | None:
    match = re.match(r"^(?P<timestamp>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) (?P<level>\S+) (?P<message>.*)$", line)
    if match:
        return match.groupdict()
    return None

def analyze_log_file(filename: Path) -> Tuple[int, Dict[str, int], Set[str]]:
    total_entries = 0
    level_counts: Dict[str, int] = {"INFO": 0, "ERROR": 0, "WARNING": 0}
    unique_users: Set[str] = set()

    with filename.open("r") as f:
        for line in f:
            entry = parse_log_line(line.strip())
            if entry:
                total_entries += 1
                level = entry["level"]
                message = entry["message"].lower()

                if level in level_counts:
                    level_counts[level] += 1

                if "alice" in message:
                    unique_users.add("alice")
                if "bob" in message:
                    unique_users.add("bob")

    return total_entries, level_counts, unique_users

def calculate_percentage(count: int, total: int) -> int:
    if total == 0:
        return 0
    return round((count / total) * 100)

def main() -> None:
    log_path = Path(LOG_FILENAME)

    create_log_file(log_path, LOG_CONTENT)

    total_entries, level_counts, unique_users = analyze_log_file(log_path)

    print(f"Total log entries: {total_entries}")
    for level_name in ["INFO", "ERROR", "WARNING"]:
        count = level_counts.get(level_name, 0)
        percentage_val = calculate_percentage(count, total_entries)
        print(f"{level_name}: {count} ({percentage_val}%)")

    sorted_users = sorted(list(unique_users))
    print(f"Unique users: {', '.join(sorted_users)}")

if __name__ == "__main__":
    main()

