from typing import TypeVar, Generic, Union, Callable, List

T = TypeVar('T')
U = TypeVar('U')

class Some(Generic[T]):
    def __init__(self, value: T) -> None:
        if value is None:
            raise ValueError("Some(value) cannot be None.")
        self.value = value

    def __repr__(self) -> str:
        return f"Some({self.value!r})"

Option = Union[Some[T], None]

def findFirst(predicate: Callable[[T], bool], items: List[T]) -> Option[T]:
    for item in items:
        if predicate(item):
            return Some(item)
    return None

def mapOption(fn: Callable[[T], U], option: Option[T]) -> Option[U]:
    if isinstance(option, Some):
        return Some(fn(option.value))
    return None

