pure func concat[a](xs: List[a], ys: List[a]) -> List[a] {
  match xs {
    [] => ys,
    x :: rest => x :: concat(rest, ys)
  }
}

pure func filter[a](pred: a -> bool, xs: List[a]) -> List[a] {
  match xs {
    [] => [],
    x :: rest => if pred(x) then x :: filter(pred, rest) else filter(pred, rest)
  }
}

pure func mapTree(fn: int -> int, tree: Tree) -> Tree {
  match tree {
    Leaf(v) => Leaf(fn(v)),
    Node(l, v, r) => Node(mapTree(fn, l), fn(v), mapTree(fn, r))
  }
}

pure func foldTree(fn: int -> int -> int, acc: int, tree: Tree) -> int {
  match tree {
    Leaf(v) => fn(acc)(v),
    Node(l, v, r) => {
      let accLeft = foldTree(fn, acc, l);
      let accV = fn(accLeft)(v);
      foldTree(fn, accV, r)
    }
  }
}

pure func treeToList(tree: Tree) -> List[int] {
  match tree {
    Leaf(v) => [v],
    Node(l, v, r) => concat(treeToList(l), v :: treeToList(r))
  }
}

pure func treeDepth(tree: Tree) -> int {
  match tree {
    Leaf(_) => 1,
    Node(l, _, r) => {
      let lDepth = treeDepth(l);
      let rDepth = treeDepth(r);
      1 + (if lDepth > rDepth then lDepth else rDepth)
    }
  }
}

